"""Owner's doc (v47): home store status during trial; draft orders create / invoice / card / mark as paid / due later; abandoned checkouts only from real shoppers;
customers list + page; segments from a description; companies with plan access and the full Add company form."""
import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import vt
from vt import ok, go
from playwright.sync_api import sync_playwright
T = lambda pg, s='#main': pg.evaluate("(document.querySelector(%r)||{}).innerText||''" % s)
